def _chunks(items: List[Any], size: int) -> Iterable[List[Any]]:
    for start in range(0, len(items), size):
        yield items[start : start + size]


def _topic_id(topic: Dict[str, Any]) -> int:
    rows = (
        supabase_admin.table("topics")
        .select("id")
        .eq("language_code", LANGUAGE_CODE)
        .eq("name", topic["name"])
        .order("id")
        .limit(2)
        .execute()
        .data
        or []
    )
    if len(rows) > 1:
        raise RuntimeError(f"Có nhiều chủ đề trùng tên {topic['name']!r}.")
    if rows:
        topic_id = int(rows[0]["id"])
        update_data: Dict[str, Any] = {
            "description": topic["description"],
            "icon_url": topic.get("icon_url"),
            "sort_order": topic["sort_order"],
        }
        if "readings" in topic and topic["readings"] is not None:
            update_data["readings"] = topic["readings"]
        supabase_admin.table("topics").update(update_data).eq("id", topic_id).execute()
        return topic_id

    insert_data: Dict[str, Any] = {
        "language_code": LANGUAGE_CODE,
        "name": topic["name"],
        "description": topic["description"],
        "icon_url": topic.get("icon_url"),
        "sort_order": topic["sort_order"],
    }
    if "readings" in topic and topic["readings"] is not None:
        insert_data["readings"] = topic["readings"]

    inserted = (
        supabase_admin.table("topics")
        .insert(insert_data)
        .execute()
    )
    if not inserted.data:
        raise RuntimeError(f"Không tạo được chủ đề {topic['name']!r}.")
    return int(inserted.data[0]["id"])


def _existing_words() -> Dict[str, int]:
    first_page = (
        supabase_admin.table("words")
        .select("id,word", count="exact")
        .eq("language_code", LANGUAGE_CODE)
        .order("id")
        .range(0, 499)
        .execute()
    )
    rows = list(first_page.data or [])
    total = int(first_page.count or 0)
    for start in range(500, total, 500):
        page = (
            supabase_admin.table("words")
            .select("id,word")
            .eq("language_code", LANGUAGE_CODE)
            .order("id")
            .range(start, min(start + 499, total - 1))
            .execute()
        )
        rows.extend(page.data or [])

    words: Dict[str, int] = {}
    for row in rows:
        normalized = str(row["word"]).strip().casefold()
        if normalized not in words:
            words[normalized] = int(row["id"])
    return words


def main() -> None:
    expected_word_count = 600
    entries = [
        (topic, word)
        for topic in TOPICS
        for word in topic["words"]
    ]
    if len(entries) != expected_word_count:
        raise RuntimeError(
            f"Seed phải có đúng {expected_word_count} từ, hiện có {len(entries)}."
        )

    topic_ids = {topic["name"]: _topic_id(topic) for topic in TOPICS}
    existing_words = _existing_words()
    pending_words: Dict[str, dict] = {}
    words_to_update: List[dict] = []

    for _, word in entries:
        normalized = word["word"].strip().casefold()
        if normalized not in existing_words:
            pending_words.setdefault(
                normalized,
                {
                    "language_code": LANGUAGE_CODE,
                    "word": word["word"],
                    "phonetic": word["phonetic"],
                    "meaning": word["meaning"],
                    "part_of_speech": word["part_of_speech"],
                    "example_sentence": word["example_sentence"],
                    "example_meaning": word["example_meaning"],
                    "level": word["level"],
                    "audio_url": word["audio_url"],
                },
            )
        else:
            words_to_update.append(
                {
                    "id": existing_words[normalized],
                    "phonetic": word["phonetic"],
                    "meaning": word["meaning"],
                    "part_of_speech": word["part_of_speech"],
                    "example_sentence": word["example_sentence"],
                    "example_meaning": word["example_meaning"],
                    "level": word["level"],
                }
            )

    inserted_count = 0
    for batch in _chunks(list(pending_words.values()), WORDS_PER_BATCH):
        created = supabase_admin.table("words").insert(batch).execute()
        if len(created.data or []) != len(batch):
            raise RuntimeError("Không ghi được đầy đủ từ vựng trong lô hiện tại.")
        for row in created.data:
            existing_words[str(row["word"]).strip().casefold()] = int(row["id"])
        inserted_count += len(created.data)

    for item in words_to_update:
        supabase_admin.table("words").update(
            {
                "phonetic": item["phonetic"],
                "meaning": item["meaning"],
                "part_of_speech": item["part_of_speech"],
                "example_sentence": item["example_sentence"],
                "example_meaning": item["example_meaning"],
                "level": item["level"],
            }
        ).eq("id", item["id"]).execute()

    links = [
        {
            "word_id": existing_words[word["word"].strip().casefold()],
            "topic_id": topic_ids[topic["name"]],
        }
        for topic, word in entries
    ]
    for batch in _chunks(links, WORDS_PER_BATCH):
        supabase_admin.table("word_topics").upsert(
            batch,
            on_conflict="word_id,topic_id",
            ignore_duplicates=True,
        ).execute()

    print(
        f"Seed hoàn tất: {len(entries)} từ trong {len(TOPICS)} chủ đề; "
        f"đã thêm {inserted_count} từ mới, cập nhật {len(words_to_update)} từ và xử lý {len(links)} liên kết chủ đề."
    )


if __name__ == "__main__":
    main()
